function safeApplyEffect(layer, effectName) {
    try {
        var fx = layer.effect.addProperty(effectName);

        if (!fx || (fx instanceof Error) || (typeof fx === "error")) {
            $.writeln("警告: 效果添加失败 " + effectName);
            return null;
        }
        return fx;
    } catch (e) {
        $.writeln("警告: 无法添加效果 " + effectName + ": " + e.toString());
        return null;
    }
}

function safeSetValue(prop, value) {
    try {
        if (!prop) { $.writeln("警告: prop为null/undefined"); return; }
        if (typeof prop.setValue !== "function") {
            $.writeln("警告: prop没有setValue方法，可能是Error对象");
            return;
        }
        if (typeof value === "string" && value.match(/wiggle|loopOut|ease\(|time\s*\*/)) {
            if (prop.canSetExpression) {
                prop.expression = value;
            }
            return;
        }
        prop.setValue(value);
    } catch (e) {
        $.writeln("警告: 设置属性失败: " + e.toString());
    }
}

function safeGetProp(fx, indexOrName) {
    try {
        if (!fx) return null;
        var prop = fx(indexOrName);
        if (!prop) return null;


        var pn = prop.name;
        if (pn === "Error" || pn === "error") return null;
        return prop;
    } catch(e) { return null; }
}

function safeSetExpression(fx, indexOrName, expr) {
    var prop = safeGetProp(fx, indexOrName);
    if (prop) {
        try {
            if (prop.canSetExpression !== false) {
                prop.expression = expr;
            }
        } catch(e) { $.writeln("警告: 设置表达式失败: " + e.toString()); }
    }
}

function safeSetValueAt(fx, indexOrName, value) {
    var prop = safeGetProp(fx, indexOrName);
    if (prop) {
        safeSetValue(prop, value);
    }
}

function safeSetValueAtTime(fx, indexOrName, time, value) {
    var prop = safeGetProp(fx, indexOrName);
    if (prop) {
        try { prop.setValueAtTime(time, value); } catch(e) { $.writeln("警告: 设置关键帧失败: " + e.toString()); }
    }
}

